import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import { Type } from 'class-transformer';
import { IsInt, IsOptional, IsString, Matches, Max, MaxLength, Min } from 'class-validator';

/**
 * Path/query validation for the payments controller.
 * The global ValidationPipe (whitelist + forbidNonWhitelisted + transform) enforces these,
 * so malformed ids never reach the database layer.
 */

/** Payment references are generated by us as `EW-PAY-` + 16 uppercase hex characters. */
export class ReferenceParamDto {
  @ApiProperty({ example: 'EW-PAY-ABC123DEF456AB78' })
  @IsString()
  @Matches(/^EW-PAY-[0-9A-F]{16}$/, { message: 'Invalid payment reference' })
  reference!: string;
}

/** Order ids are cuids: short, URL-safe tokens. Reject anything else early. */
export class OrderIdParamDto {
  @ApiProperty({ description: 'Order CUID', example: 'cmvgsakrq000008jvqsd0yrt4' })
  @IsString()
  @Matches(/^[A-Za-z0-9_-]{10,40}$/, { message: 'Invalid order id' })
  orderId!: string;
}

export class PaymentHistoryQueryDto {
  @ApiPropertyOptional({ example: 20, minimum: 1, maximum: 100 })
  @IsOptional()
  @Type(() => Number)
  @IsInt()
  @Min(1)
  @Max(100)
  limit?: number;

  @ApiPropertyOptional({ description: 'Last ID from previous page for cursor pagination' })
  @IsOptional()
  @IsString()
  @MaxLength(64)
  @Matches(/^[A-Za-z0-9_-]+$/, { message: 'Invalid cursor' })
  cursor?: string;
}
